<?php
/** ThreadFlow - Buyer Change Request Details. */
require_once __DIR__ . '/../../includes/auth.php';
require_role(['admin', 'merchandiser']);
$requestId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT);
if (!$requestId || $requestId <= 0) { flash_set('error', 'Invalid change request ID specified.'); redirect('modules/buyer_change_requests/index.php'); }
try {
    $stmt = $conn->prepare('SELECT bcr.*, bo.order_number, bo.style_number, bo.total_quantity, bo.order_date, bo.delivery_date, bo.status AS order_status, b.buyer_id, b.buyer_name, req.full_name AS requester_name, req.username AS requester_username, rev.full_name AS reviewer_name FROM buyer_change_requests bcr INNER JOIN buyer_orders bo ON bo.order_id = bcr.order_id INNER JOIN buyers b ON b.buyer_id = bo.buyer_id INNER JOIN users req ON req.user_id = bcr.requester_id LEFT JOIN users rev ON rev.user_id = bcr.reviewed_by WHERE bcr.request_id = ? LIMIT 1');
    if (!$stmt) { throw new mysqli_sql_exception('Request detail query could not be prepared.'); }
    $stmt->bind_param('i', $requestId); $stmt->execute(); $request = $stmt->get_result()->fetch_assoc(); $stmt->close();
    if (!$request) { flash_set('error', 'Buyer change request not found.'); redirect('modules/buyer_change_requests/index.php'); }
    $batchStmt = $conn->prepare('SELECT batch_number, planned_quantity, status, start_date, target_end_date FROM production_batches WHERE order_id = ? ORDER BY batch_id');
    $batchStmt->bind_param('i', $request['order_id']); $batchStmt->execute(); $batches = $batchStmt->get_result()->fetch_all(MYSQLI_ASSOC); $batchStmt->close();
} catch (mysqli_sql_exception $e) { error_log('Database exception loading buyer change request: ' . $e->getMessage()); flash_set('error', 'A database error occurred while loading the request.'); redirect('modules/buyer_change_requests/index.php'); }
$pageTitle = 'Change Request #' . $requestId; $currentNav = 'buyer_change_requests';
function bcr_view_badge(string $value): string { return $value === 'Critical' || $value === 'Rejected' ? 'badge-danger' : ($value === 'High' ? 'badge-warning' : ($value === 'Approved' || $value === 'Low' ? 'badge-success' : 'badge-info')); }
include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Buyer Change Request #<?= (int) $request['request_id'] ?></h1><div class="page-subtitle">Order <?= e($request['order_number']) ?> &bull; Submitted <?= e($request['requested_at']) ?></div></div><div class="page-actions"><?php if ($userRole === 'admin' && $request['status'] === 'Submitted'): ?><a href="<?= e(url('modules/buyer_change_requests/review.php?id=' . $requestId)) ?>" class="btn btn-primary">Review Request</a><?php endif; ?><a href="<?= e(url('modules/buyer_change_requests/index.php')) ?>" class="btn btn-secondary">Back to List</a></div></div>
<div class="card mb-4"><div class="card-header"><h2>Request Summary</h2><div><span class="badge <?= e(bcr_view_badge($request['impact_level'])) ?>"><?= e($request['impact_level']) ?> Impact</span> <span class="badge <?= e(bcr_view_badge($request['status'])) ?>"><?= e($request['status']) ?></span></div></div><div class="card-body"><div class="details-grid"><div><span class="form-label">Order</span><p><a href="<?= e(url('modules/orders/view.php?id=' . (int) $request['order_id'])) ?>"><?= e($request['order_number']) ?></a></p></div><div><span class="form-label">Buyer</span><p><?= e($request['buyer_name']) ?></p></div><div><span class="form-label">Style</span><p><?= e($request['style_number']) ?></p></div><div><span class="form-label">Order Quantity</span><p><?= number_format((int) $request['total_quantity']) ?> pcs</p></div><div><span class="form-label">Order Status</span><p><?= e($request['order_status']) ?></p></div><div><span class="form-label">Change Type</span><p><?= e($request['change_type']) ?></p></div><div><span class="form-label">Current Value</span><p><?= e($request['current_value']) ?></p></div><div><span class="form-label">Requested New Value</span><p><?= e($request['requested_value']) ?></p></div><div><span class="form-label">Affected Quantity</span><p><?= $request['affected_quantity'] === null ? 'Not specified' : number_format((int) $request['affected_quantity']) . ' pcs' ?></p></div><div><span class="form-label">Requester</span><p><?= e($request['requester_name']) ?> (<?= e($request['requester_username']) ?>)</p></div></div><div class="form-group"><span class="form-label">Reason / Details</span><p><?= nl2br(e($request['reason_details'])) ?></p></div></div></div>
<div class="card mb-4"><div class="card-header"><h2>Production Impact Analysis</h2><span class="badge <?= e(bcr_view_badge($request['impact_level'])) ?>"><?= e($request['impact_level']) ?></span></div><div class="card-body"><p><strong>Recommended action:</strong> <?= e($request['recommended_action']) ?></p><?php if (!$batches): ?><p class="text-muted">No related production batches exist. Production has not started.</p><?php else: ?><div class="table-responsive"><table class="table"><thead><tr><th>Batch</th><th>Planned Quantity</th><th>Status</th><th>Timeline</th></tr></thead><tbody><?php foreach ($batches as $batch): ?><tr><td><?= e($batch['batch_number']) ?></td><td><?= number_format((int) $batch['planned_quantity']) ?> pcs</td><td><?= e($batch['status']) ?></td><td><?= e($batch['start_date']) ?> to <?= e($batch['target_end_date']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></div></div>
<div class="card"><div class="card-header"><h2>Decision</h2></div><div class="card-body"><?php if ($request['status'] === 'Submitted'): ?><p class="text-muted">This request is awaiting Admin review. The original buyer order remains unchanged.</p><?php else: ?><div class="details-grid"><div><span class="form-label">Decision</span><p><?= e($request['status']) ?></p></div><div><span class="form-label">Reviewed By</span><p><?= e($request['reviewer_name'] ?: 'Unknown') ?></p></div><div><span class="form-label">Reviewed At</span><p><?= e($request['reviewed_at']) ?></p></div></div><div class="form-group"><span class="form-label">Review Notes</span><p><?= nl2br(e($request['review_notes'])) ?></p></div><?php endif; ?></div></div>
<?php include __DIR__ . '/../../includes/footer.php'; ?>
